-- Binärfragen (5 Stück)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind funktionale Anforderungen immer wichtiger als nicht funktionale Anforderungen bei der Erstellung eines Anforderungskatalogs?', 2, '[{"text": "Nein", "correct": true, "because": "Priorität hängt vom Projekt ab, beide sind essenziell"}, {"text": "Ja", "correct": false, "because": "Nicht funktionale Anforderungen können entscheidend sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen alle Anforderungen eines Katalogs messbar formuliert sein, um umsetzbar zu sein?', 2, '[{"text": "Nein", "correct": true, "because": "Qualitative Anforderungen sind oft schwer messbar, aber relevant"}, {"text": "Ja", "correct": false, "because": "Messbarkeit ist ideal, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Barrierefreiheit eine nicht funktionale Anforderung, die in jedem Projekt berücksichtigt werden muss?', 2, '[{"text": "Nein", "correct": true, "because": "Pflicht nur bei gesetzlichen oder projektspezifischen Vorgaben"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Kontext, nicht universell vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Können funktionale Anforderungen die Benutzerfreundlichkeit eines Systems vollständig definieren?', 2, '[{"text": "Nein", "correct": true, "because": "Benutzerfreundlichkeit ist meist nicht funktional"}, {"text": "Ja", "correct": false, "because": "Nicht funktionale Aspekte wie Usability sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Anforderungskatalog nur dann vollständig, wenn er alle potenziellen Nutzergruppen abdeckt?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus liegt auf relevanten Nutzern, nicht allen denkbaren"}, {"text": "Ja", "correct": false, "because": "Vollständigkeit ist projektabhängig definiert"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für die Erstellung eines Anforderungskatalogs am wenigsten geeignet?', 3, '[{"text": "Vage Formulierungen", "correct": true, "because": "Undeutliche Anforderungen führen zu Missverständnissen"}, {"text": "Klar definierte Akzeptanzkriterien", "correct": false, "because": "Diese erhöhen die Präzision"}, {"text": "Priorisierung der Anforderungen", "correct": false, "because": "Hilft bei der Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche nicht funktionale Anforderung hat den größten Einfluss auf die Systemarchitektur?', 2, '[{"text": "Skalierbarkeit", "correct": true, "because": "Beeinflusst Design und Ressourcenplanung"}, {"text": "Farbschema der Benutzeroberfläche", "correct": false, "because": "Oberflächlich, nicht strukturell"}, {"text": "Installationszeit", "correct": false, "because": "Wichtig, aber weniger architektonisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft am besten, Barrierefreiheitsanforderungen im Katalog zu spezifizieren?', 3, '[{"text": "Verweis auf WCAG-Richtlinien", "correct": true, "because": "Bietet klare, internationale Standards"}, {"text": "Interne Design-Vorgaben", "correct": false, "because": "Weniger verbindlich"}, {"text": "Feedback von Entwicklern", "correct": false, "because": "Subjektiv und nicht normativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die Hauptaufgabe funktionaler Anforderungen im Anforderungskatalog?', 2, '[{"text": "Beschreibung des Systemverhaltens", "correct": true, "because": "Definiert, was das System tun soll"}, {"text": "Festlegung der Betriebszeiten", "correct": false, "because": "Das ist nicht funktional"}, {"text": "Sicherstellung der Wartbarkeit", "correct": false, "because": "Das ist eine Qualitätsanforderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt wird häufig bei der Formulierung von Anforderungen übersehen?', 3, '[{"text": "Nachprüfbarkeit der Anforderung", "correct": true, "because": "Ohne Prüfkriterien bleibt die Umsetzung unklar"}, {"text": "Technische Machbarkeit", "correct": false, "because": "Wird oft früh geprüft"}, {"text": "Kostenabschätzung", "correct": false, "because": "Häufig separat betrachtet"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kategorien gehören typischerweise zu nicht funktionalen Anforderungen?', 4, '[{"text": "Performance", "correct": true, "because": "Beeinflusst Systemeffizienz"}, {"text": "Benutzerregistrierung", "correct": false, "because": "Das ist funktional"}, {"text": "Sicherheit", "correct": true, "because": "Schützt das System"}, {"text": "Barrierefreiheit", "correct": true, "because": "Fördert Zugänglichkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen einen Anforderungskatalog effektiv?', 3, '[{"text": "Klarheit und Eindeutigkeit", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Maximale Anzahl an Anforderungen", "correct": false, "because": "Quantität ist nicht entscheidend"}, {"text": "Priorisierung der Punkte", "correct": true, "because": "Fokussiert Umsetzung"}, {"text": "Nachvollziehbare Begründungen", "correct": true, "because": "Erhöht Akzeptanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Barrierefreiheit sollten im Anforderungskatalog berücksichtigt werden?', 4, '[{"text": "Kontrastreiche Farben", "correct": true, "because": "Wichtig für Sehbehinderte"}, {"text": "Schnelle Ladezeiten", "correct": false, "because": "Performance, nicht Barrierefreiheit"}, {"text": "Tastaturnavigation", "correct": true, "because": "Ermöglicht Nutzung ohne Maus"}, {"text": "Screenreader-Kompatibilität", "correct": true, "because": "Unterstützt Blinde"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fehler können bei der Erstellung eines Anforderungskatalogs auftreten?', 3, '[{"text": "Unklare Formulierungen", "correct": true, "because": "Führt zu Interpretationsproblemen"}, {"text": "Fehlende Priorisierung", "correct": true, "because": "Erschwert Entscheidungen"}, {"text": "Zu detaillierte technische Beschreibungen", "correct": true, "because": "Begrenzt Entwurfsfreiheit"}, {"text": "Automatische Umsetzung", "correct": false, "because": "Kein Fehler, sondern Illusion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Erstellung eines Anforderungskatalogs wichtig?', 3, '[{"text": "Stakeholder-Befragung", "correct": true, "because": "Erfasst Bedürfnisse"}, {"text": "Analyse bestehender Systeme", "correct": true, "because": "Liefert Kontext"}, {"text": "Festlegung der Programmiersprache", "correct": false, "because": "Zu früh in dieser Phase"}, {"text": "Definition von Akzeptanzkriterien", "correct": true, "because": "Macht Erfolg messbar"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Funktionale Anforderungen beschreiben, wie ein System reagieren soll. b) Barrierefreiheit ist nur für öffentliche Projekte relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Funktionalität wird definiert, Barrierefreiheit ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nicht funktionale Anforderungen können die Wahl der Technologie beeinflussen. b) Ein Anforderungskatalog muss alle technischen Details enthalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technologie hängt von Anforderungen ab, Details gehören in den Entwurf"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Barrierefreiheit erhöht oft die Entwicklungszeit. b) Funktionale Anforderungen sollten technische Lösungen vorschreiben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Barrierefreiheit kann Aufwand erhöhen, funktionale Anforderungen bleiben lösungsneutral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Anforderungskatalog sollte widerspruchsfrei sein. b) Nicht funktionale Anforderungen sind immer optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Widersprüche erschweren Umsetzung, nicht funktionale Anforderungen können zwingend sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Funktionale Anforderungen können durch Use Cases beschrieben werden. b) Barrierefreiheit hat keinen Einfluss auf die Systemleistung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Use Cases sind geeignet, Barrierefreiheit kann Performance beeinflussen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

